use std::{future::Future,io::Write,sync::Arc,task::{Context,Poll,Wake,Waker},time::Duration};
struct TW(std::thread::Thread);
impl Wake for TW {fn wake(self:Arc<Self>){self.0.unpark();}fn wake_by_ref(self:&Arc<Self>){self.0.unpark();}}
fn block_on<T>(f:impl Future<Output=T>)->T{let mut f=std::pin::pin!(f);let w=Waker::from(Arc::new(TW(std::thread::current())));let mut cx=Context::from_waker(&w);loop{match f.as_mut().poll(&mut cx){Poll::Ready(v)=>return v,Poll::Pending=>std::thread::park_timeout(Duration::from_millis(1))}}}
fn save(p:&str,b:&[u8]){let mut f=std::fs::OpenOptions::new().write(true).create_new(true).open(p).unwrap();f.write_all(b).unwrap();f.sync_all().unwrap();}
fn address(s:&str)->wgpu::AddressMode{match s{"Repeat"=>wgpu::AddressMode::Repeat,"Clamp"=>wgpu::AddressMode::ClampToEdge,"Mirror"=>wgpu::AddressMode::MirrorRepeat,_=>panic!("Unsupported native wrap {s}")}}
fn main(){
 let args:Vec<_>=std::env::args().collect();let native:serde_json::Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();
 let instance=wgpu::Instance::new(wgpu::InstanceDescriptor{backends:wgpu::Backends::DX12,..wgpu::InstanceDescriptor::new_without_display_handle()});
 let adapter=block_on(instance.request_adapter(&wgpu::RequestAdapterOptions{power_preference:wgpu::PowerPreference::HighPerformance,force_fallback_adapter:false,compatible_surface:None})).unwrap();let info=adapter.get_info();assert_eq!(info.backend,wgpu::Backend::Dx12);
 assert!(adapter.features().contains(wgpu::Features::FLOAT32_FILTERABLE),"No float32 texture filtering; do not quantize source heights");
 let (device,queue)=block_on(adapter.request_device(&wgpu::DeviceDescriptor{label:Some("Source House POM comparison"),required_features:wgpu::Features::FLOAT32_FILTERABLE,required_limits:adapter.limits(),..Default::default()})).unwrap();
 let module=device.create_shader_module(wgpu::ShaderModuleDescriptor{label:Some("Pinned SDK POM WGSL"),source:wgpu::ShaderSource::Wgsl(include_str!("pom.wgsl").into())});
 let pipeline=device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor{label:None,layout:None,module:&module,entry_point:Some("pom"),compilation_options:Default::default(),cache:None});let mut receipts=Vec::new();
 for row in native["materials"].as_array().unwrap(){
  let input_path=std::path::Path::new(row["raw_output"].as_str().unwrap()).with_file_name("INPUT.f32");let data=std::fs::read(input_path).unwrap();let count=row["samples"].as_u64().unwrap();assert_eq!(data.len() as u64,count*80);
  let width=row["width"].as_u64().unwrap() as u32;let height=row["height"].as_u64().unwrap() as u32;let red=std::fs::read(row["height_output"].as_str().unwrap()).unwrap();assert_eq!(red.len(),(width*height*4) as usize);
  let texture=device.create_texture(&wgpu::TextureDescriptor{label:Some("Native GPU decoded height mip zero"),size:wgpu::Extent3d{width,height,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::R32Float,usage:wgpu::TextureUsages::TEXTURE_BINDING|wgpu::TextureUsages::COPY_DST,view_formats:&[]});
  queue.write_texture(wgpu::TexelCopyTextureInfo{texture:&texture,mip_level:0,origin:wgpu::Origin3d::ZERO,aspect:wgpu::TextureAspect::All},&red,wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(width*4),rows_per_image:Some(height)},wgpu::Extent3d{width,height,depth_or_array_layers:1});
  let view=texture.create_view(&Default::default());let filter=match row["filter"].as_str().unwrap(){"Point"=>wgpu::FilterMode::Nearest,"Bilinear"|"Trilinear"=>wgpu::FilterMode::Linear,s=>panic!("Unsupported filter {s}")};
  let sampler=device.create_sampler(&wgpu::SamplerDescriptor{label:None,address_mode_u:address(row["wrap_u"].as_str().unwrap()),address_mode_v:address(row["wrap_v"].as_str().unwrap()),mag_filter:filter,min_filter:filter,lod_min_clamp:0.0,lod_max_clamp:0.0,..Default::default()});
  let input=device.create_buffer(&wgpu::BufferDescriptor{label:None,size:data.len() as u64,usage:wgpu::BufferUsages::STORAGE|wgpu::BufferUsages::COPY_DST,mapped_at_creation:false});queue.write_buffer(&input,0,&data);let size=count*16;
  let output=device.create_buffer(&wgpu::BufferDescriptor{label:None,size,usage:wgpu::BufferUsages::STORAGE|wgpu::BufferUsages::COPY_SRC,mapped_at_creation:false});let readback=device.create_buffer(&wgpu::BufferDescriptor{label:None,size,usage:wgpu::BufferUsages::MAP_READ|wgpu::BufferUsages::COPY_DST,mapped_at_creation:false});
  let binding=device.create_bind_group(&wgpu::BindGroupDescriptor{label:None,layout:&pipeline.get_bind_group_layout(0),entries:&[wgpu::BindGroupEntry{binding:0,resource:wgpu::BindingResource::TextureView(&view)},wgpu::BindGroupEntry{binding:1,resource:wgpu::BindingResource::Sampler(&sampler)},wgpu::BindGroupEntry{binding:2,resource:input.as_entire_binding()},wgpu::BindGroupEntry{binding:3,resource:output.as_entire_binding()}]});
  let mut encoder=device.create_command_encoder(&Default::default());{let mut pass=encoder.begin_compute_pass(&wgpu::ComputePassDescriptor{label:None,timestamp_writes:None});pass.set_pipeline(&pipeline);pass.set_bind_group(0,&binding,&[]);pass.dispatch_workgroups((count as u32).div_ceil(64),1,1);}encoder.copy_buffer_to_buffer(&output,0,&readback,0,size);let submission=queue.submit([encoder.finish()]);
  let(tx,rx)=std::sync::mpsc::channel();readback.slice(..).map_async(wgpu::MapMode::Read,move |r|tx.send(r).unwrap());device.poll(wgpu::PollType::Wait{submission_index:Some(submission),timeout:Some(Duration::from_secs(30))}).unwrap();rx.recv_timeout(Duration::from_secs(30)).unwrap().unwrap();let mapped=readback.slice(..).get_mapped_range();for b in mapped.chunks_exact(4){assert!(f32::from_le_bytes(b.try_into().unwrap()).is_finite());}
  let result=std::path::Path::new(&args[2]).join(format!("{}.f32",row["guid"].as_str().unwrap()));save(result.to_str().unwrap(),&mapped);drop(mapped);readback.unmap();receipts.push(serde_json::json!({"guid":row["guid"],"samples":count,"output_bytes":size,"output":result,"texture_storage":"R32Float native decoded red mip0","native_aniso":row["aniso"],"aniso_qualified":row["aniso"].as_u64().unwrap()<=1,"lod":0}));
 }
 let receipt=serde_json::json!({"adapter":info.name,"backend":format!("{:?}",info.backend),"driver":info.driver,"driver_info":info.driver_info,"float32_filterable":true,"materials":receipts,"full_import":false,"render_parity":false});save(&args[3],&serde_json::to_vec_pretty(&receipt).unwrap());println!("{}",receipt);
}
